    );
    model = _send(model, OutputMsg('seed', newline: true));
    model = _send(model, KeyPressMsg(const TeaKey(code: KeyCode.pageUp)));
    expect(model.follow.isHeld, isTrue);
    final before = _rowsOf(model).take(19).join('\n');

    model = _send(model, OutputMsg('tick', newline: true));
    expect(model.follow.isHeld, isTrue);
    final after = _rowsOf(model).take(19).join('\n');
    if (before != after) {
      // Show the drift.
      final beforeRows = before.split('\n');
      final afterRows = after.split('\n');
      for (var i = 0; i < beforeRows.length; i++) {
        if (beforeRows[i] != afterRows[i]) {
          // ignore: avoid_print
          print('drift at visible row $i:\n  before: ${beforeRows[i]}\n'
              '  after:  ${afterRows[i]}');
          break;
        }
      }
    }
    expect(before, after,
        reason: 'E1: the head trim must not shift what the user is reading');
  });
}

