      final total = _lastSynced.length;
      if (index == null || index < 0 || index >= total || total < 2) return;
      final fraction = (total - 1 - index) / (total - 1);
      _chatScrollController.jumpTo(
        fraction * _chatScrollController.position.maxScrollExtent,
      );
