    String line(int i) => i % 5 == 0 ? 'LONG $i ${'x' * 200}' : 'row $i';
    // 1999 lines + seed append -> 2000 lines, under the 2400 trim mark.
    var model = _build().copyWith(
      outputLines: [for (var i = 0; i < 1999; i++) line(i)],
    );
    model = _send(model, OutputMsg('seed', newline: true));
    model = _send(model, KeyPressMsg(const TeaKey(code: KeyCode.pageUp)));
    expect(model.follow.isHeld, isTrue);
    final beforeRows = _rowsOf(model);
    // ignore: avoid_print
    print('held: anchor=${model.heldAnchorLine} offset=${model.scrollOffset} '
        'lines=${model.outputLines.length}');
    // ignore: avoid_print
    print('top visible before: ${beforeRows.take(5).join(' | ')}');

    // One big multi-line append crosses the 2400 mark -> cut fires while held.
    model = _send(
      model,
      OutputMsg(
        [for (var i = 0; i < 500; i++) 'burst $i'].join('\n'),
        newline: true,
