    }
    final trimmedRows = _heldAnchorShiftedByCut(cut);
    final reanchored = next.copyWith(
      heldAnchorLine: trimmedRows.$1,
      scrollOffset: trimmedRows.$2,
      follow: follow.appended(1),
    );
    return (reanchored, null);
  }

