    await tester.pump(const Duration(milliseconds: 100));

    final pill = find.byKey(const ValueKey('faChatJumpToLivePill'));
    expect(pill, findsOneWidget);
    expect(
      find.text('⌄ 7 new'),
      findsOneWidget,
      reason: 'the pill counts live (AC2)',
