    m.view().content.split('\n').map((r) => stripAnsi(r)).toList();

void main() {
  test('scratch: variable-height lines — trim drift', () {
    // Lines with variable wrapped heights: every 5th line is long and
    // wraps to several rows at width 80.
    String line(int i) =>
        i % 5 == 0 ? 'LONG $i ${'x' * 200}' : 'row $i';
    var model = _build().copyWith(
      outputLines: [for (var i = 0; i < 2400; i++) line(i), 'TAIL-MARK'],
    );
