    print('top visible after: ${afterRows.take(5).join(' | ')}');
    final same = beforeRows.take(19).join('\n') == afterRows.take(19).join('\n');
    // ignore: avoid_print
    print('window identical: $same');
    expect(same, isTrue,
        reason: 'E1: the held window must not shift when a trim fires');
  });
}
