import 'package:dart_tui/dart_tui.dart' hide stripAnsi;

import 'package:flutter_agent_harness/src/approval/approval.dart';
import 'package:flutter_agent_harness/src/cli/fa_tui.dart';
import 'package:flutter_agent_harness/src/cli/tui_repl.dart' show stripAnsi;
import 'package:test/test.dart';

FaTuiCallbacks _callbacks() => FaTuiCallbacks(
  onSubmit: (_, {images = const []}) async {},
  onModelSelected: (_) async {},
  buildSlashMenu: (_) => const [],
  buildModelMenu: (_, _) => const [],
  statusLine: () => '/work · 0tok · turn 0 · test-model',
  prompt: 'fa> ',
);

FaTuiModel _build({int termWidth = 80, int termHeight = 24}) => FaTuiModel(
  callbacks: _callbacks(),
  isExited: () => false,
  termWidth: termWidth,
  termHeight: termHeight,
);

FaTuiModel _send(FaTuiModel m, Msg msg) => m.update(msg).$1 as FaTuiModel;

List<String> _rowsOf(FaTuiModel m) =>
    m.view().content.split('\n').map((r) => stripAnsi(r)).toList();

void main() {
  test('re-review: mid-line park survives a trim (the original repro)', () {
    String line(int i) => i % 5 == 0 ? 'LONG $i ${'x' * 200}' : 'row $i';
    var model = _build().copyWith(
      outputLines: [for (var i = 0; i < 1999; i++) line(i)],
    );
    model = _send(model, OutputMsg('seed', newline: true));
    model = _send(model, KeyPressMsg(const TeaKey(code: KeyCode.pageUp)));
    expect(model.follow.isHeld, isTrue);
    final before = _rowsOf(model).take(19).join('\n');

    model = _send(
      model,
      OutputMsg(
        [for (var i = 0; i < 500; i++) 'burst $i'].join('\n'),
        newline: true,
      ),
    );
    final after = _rowsOf(model).take(19).join('\n');
    expect(
      after,
      before,
      reason: 'E1 fix: the held window must not shift on a trim '
          '(mid-line parked, irregular heights)',
    );
  });

  test('re-review: repeated trims while held stay stable', () {
    String line(int i) => i % 5 == 0 ? 'LONG $i ${'x' * 200}' : 'row $i';
    var model = _build().copyWith(
      outputLines: [for (var i = 0; i < 1999; i++) line(i)],
    );
    model = _send(model, OutputMsg('seed', newline: true));
    model = _send(model, KeyPressMsg(const TeaKey(code: KeyCode.pageUp)));
    // Three successive trim-crossing bursts: each must keep the window.
    for (var burst = 0; burst < 3; burst++) {
      final before = _rowsOf(model).take(19).join('\n');
      model = _send(
        model,
        OutputMsg(
          [for (var i = 0; i < 450; i++) 'b$burst-$i'].join('\n'),
          newline: true,
        ),
      );
      final after = _rowsOf(model).take(19).join('\n');
      expect(after, before, reason: 'burst $burst shifted the held window');
    }
  });

  test('re-review probe: fence-repair trim shape (documented 1-row drift)',
      () {
    // A dropped head that ends INSIDE an open fence triggers the
    // synthetic ``` repair (effective head shift cut-1). The rework
    // documents a bounded one-row drift there; verify it stays bounded.
    final lines = <String>['```dart', for (var i = 0; i < 1998; i++) 'pad $i'];
    var model = _build().copyWith(outputLines: lines);
    model = _send(model, OutputMsg('seed', newline: true));
    model = _send(model, KeyPressMsg(const TeaKey(code: KeyCode.pageUp)));
    expect(model.follow.isHeld, isTrue);
    final before = _rowsOf(model).take(19);
    model = _send(
      model,
      OutputMsg(
        ['```dart', ...[for (var i = 0; i < 500; i++) 'burst $i'], '```']
            .join('\n'),
        newline: true,
      ),
    );
    final after = _rowsOf(model).take(19);
    var driftRows = 0;
    for (var i = 0; i < 19; i++) {
      if (before[i] != after[i]) driftRows++;
    }
    // ignore: avoid_print
    print('fence-shape drift rows in the 19-row window: $driftRows; '
        'first diff at row ${[for (var i = 0; i < 19; i++) if (before[i] != after[i]) i].take(3).toList()}');
    expect(model.follow.isHeld, isTrue);
  });
}
